sealed class SecretHandler:HttpMessageHandler {
 internal Dictionary<string,string> Expected;internal int Calls;internal bool MissingError,Rotated;
 internal SecretHandler(Dictionary<string,string> expected){Expected=expected;}
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Calls++;Check(request.Method==HttpMethod.Post&&request.RequestUri.AbsoluteUri=="https://oauth2.googleapis.com/token"&&request.Content.Headers.ContentType.MediaType=="application/x-www-form-urlencoded"&&request.Headers.Authorization==null);var form=DecodeForm(await request.Content.ReadAsStringAsync(token));Check(form.Count==Expected.Count);foreach(var entry in Expected)Check(form.TryGetValue(entry.Key,out var actual)&&actual==entry.Value);return new(MissingError?HttpStatusCode.BadRequest:HttpStatusCode.OK){Content=new StringContent(MissingError?"{\"error\":\"invalid_request\",\"error_description\":\"client_secret is missing.\"}":JsonSerializer.Serialize(new{access_token="synthetic-new-access",refresh_token=Rotated?"synthetic-rotated-refresh":"",token_type="Bearer",expires_in=3600,scope=YouTubePkceSession.Scope}),Encoding.UTF8,"application/json")};}
}
sealed class PlainSecretProtection:IYouTubeDataProtection {readonly byte[] plain;internal PlainSecretProtection(string json){plain=Encoding.UTF8.GetBytes(json);}public byte[] Protect(byte[] value)=>throw new Exception("unused");public byte[] Unprotect(byte[] value)=>plain.ToArray();}
static string SecretPayload(string id=Id,string secret=FakeDesktopSecret)=>JsonSerializer.Serialize(new{kind="desktop-client-secret-v1",client_id=id,client_secret=secret});
static string SecretFixture(string json){string dir=Temp();Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,YouTubeProtectedClientSecret.FileName),new byte[]{1});return dir;}
static string ReadFixture(string json,string id=Id){string dir=SecretFixture(json);return new YouTubeProtectedClientSecret(dir,new PlainSecretProtection(json)).Load(id);}
static string ConfigFile(string dir,string id=Id){Directory.CreateDirectory(dir);string file=Path.Combine(dir,"oauth-client.json");File.WriteAllText(file,JsonSerializer.Serialize(new{client_id=id}));return file;}
static async Task<(int Exit,string Output)> ImportSecret(string google,string config,string directory,bool replace=false){var p=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32/WindowsPowerShell/v1.0/powershell.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string x in new[]{"-NoProfile","-NonInteractive","-File",Path.Combine(Environment.GetEnvironmentVariable("TOHS_VERSION_SOURCE")??throw new Exception("source root required"),"tools/Import-YouTubeDesktopClient.ps1"),"-GoogleClientJson",google,"-ClientConfiguration",config,"-CredentialDirectory",directory})p.ArgumentList.Add(x);if(replace)p.ArgumentList.Add("-ReplaceExisting");p.Environment.Remove("PSModulePath");using var process=Process.Start(p);var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(30));string output=await stdout+await stderr;Check(!output.Contains(FakeDesktopSecret)&&!output.Contains(Id)&&!output.Contains("synthetic-rotated-secret"));if(process.ExitCode!=0)Console.WriteLine("IMPORT_TEST exit="+process.ExitCode+" stage="+System.Text.RegularExpressions.Regex.Match(output,@"IMPORT_CLIENT stage=([A-Za-z]+)").Groups[1].Value+" executionPolicy="+(output.Contains("PSSecurityException")||output.Contains("UnauthorizedAccess"))+" fileArgument="+output.Contains("does not exist"));return(process.ExitCode,output);}
static async Task ClientSecretTests(){
