foreach(bool secret in new[]{false,true})await Test("auth service refresh includes only configured client secret "+secret,async()=>{var store=new Store{Data=Tokens(true)};var exchange=new Exchange();using var service=new YouTubeAuthService(new(Id,secret?FakeDesktopSecret:null),store,new Flow(),exchange);await service.GetAsync(default);Check(exchange.Refreshes==1&&exchange.Last.ContainsKey("client_secret")==secret&&exchange.Last["client_id"]==Id&&exchange.Last["grant_type"]=="refresh_token"&&store.Saves==1);if(secret)Check(exchange.Last["client_secret"]==FakeDesktopSecret);});
foreach(bool rotated in new[]{false,true})await Test("HTTP refresh preserves or rotates refresh token "+rotated,async()=>{var form=new Dictionary<string,string>{{"client_id",Id},{"grant_type","refresh_token"},{"refresh_token","synthetic-old-refresh"}};new YouTubeOAuthSettings(Id,FakeDesktopSecret).ApplyClientSecret(form);var h=new SecretHandler(new(form)){Rotated=rotated};using var oauth=new YouTubeDesktopOAuth(new HttpClient(h));var next=await oauth.ExchangeAsync(form,default,"synthetic-old-refresh");Check(next.RefreshToken==(rotated?"synthetic-rotated-refresh":"synthetic-old-refresh"));});
await Test("missing secret HTTP400 is classified without retry or disclosure",async()=>{var form=CompleteSynthetic(Session());var h=new SecretHandler(new(form)){MissingError=true};var logs=new List<string>();using var oauth=new YouTubeDesktopOAuth(new HttpClient(h),x=>logs.Add(x.SafeLog));try{await oauth.ExchangeAsync(form,default);throw new Exception("Expected rejection");}catch(YouTubeApiException e){Check(e.OAuth.Code==YouTubeOAuthCode.ClientSecretRequired&&e.OAuth.HttpStatus==400&&!e.Message.Contains(FakeDesktopSecret));}Check(h.Calls==1&&logs.All(x=>!x.Contains(FakeDesktopSecret)&&!x.Contains(Id)));});
foreach(string bad in new[]{""," ","secret\r\nInjected","\u007f","日本語",new string('s',4097)})await Test("malformed optional secret rejected "+bad.Length,()=>{try{new YouTubeOAuthSettings(Id,bad);throw new Exception("Expected rejection");}catch(ArgumentException e){Check(!e.Message.Contains(FakeDesktopSecret));}return Task.CompletedTask;});
