await Test("offline import matches client ID DPAPI and private ACL and preserves tokens",async()=>{string dir=Temp();Directory.CreateDirectory(dir);string google=Path.Combine(dir,"google.json"),config=ConfigFile(dir),output=Path.Combine(dir,"private");File.WriteAllText(google,JsonSerializer.Serialize(new{installed=new{client_id=Id,client_secret=FakeDesktopSecret}}));Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"oauth.dpapi"),"synthetic-existing-token-data");File.WriteAllText(Path.Combine(output,"oauth.disabled"),"synthetic-existing-marker");byte[] original=File.ReadAllBytes(config);var result=await ImportSecret(google,config,output);Check(result.Exit==0,"offline importer rejected synthetic configuration");string file=Path.Combine(output,YouTubeProtectedClientSecret.FileName);Check(!Encoding.UTF8.GetString(File.ReadAllBytes(file)).Contains(FakeDesktopSecret));var settings=YouTubeOAuthSettings.Load(config,output);var form=CompleteSynthetic(Session());settings.ApplyClientSecret(form);Check(form["client_secret"]==FakeDesktopSecret&&original.SequenceEqual(File.ReadAllBytes(config))&&File.ReadAllText(Path.Combine(output,"oauth.dpapi"))=="synthetic-existing-token-data"&&File.ReadAllText(Path.Combine(output,"oauth.disabled"))=="synthetic-existing-marker");var acl=System.IO.FileSystemAclExtensions.GetAccessControl(new FileInfo(file));using var identity=System.Security.Principal.WindowsIdentity.GetCurrent();Check(acl.AreAccessRulesProtected&&acl.GetAccessRules(true,false,typeof(System.Security.Principal.SecurityIdentifier)).Cast<System.Security.AccessControl.FileSystemAccessRule>().All(rule=>rule.IdentityReference.Equals(identity.User)),"secret file ACL must be current-user-only");Check(!Directory.GetFiles(output,"*.tmp").Any());});
