await Test("offline import replacement requires explicit opt in",async()=>{string dir=Temp();Directory.CreateDirectory(dir);string config=ConfigFile(dir),google=Path.Combine(dir,"google.json"),output=Path.Combine(dir,"private");File.WriteAllText(google,JsonSerializer.Serialize(new{installed=new{client_id=Id,client_secret=FakeDesktopSecret}}));Check((await ImportSecret(google,config,output)).Exit==0);string file=Path.Combine(output,YouTubeProtectedClientSecret.FileName);byte[] before=File.ReadAllBytes(file);File.WriteAllText(google,JsonSerializer.Serialize(new{installed=new{client_id=Id,client_secret="synthetic-rotated-secret"}}));Check((await ImportSecret(google,config,output)).Exit!=0&&before.SequenceEqual(File.ReadAllBytes(file)));Check((await ImportSecret(google,config,output,true)).Exit==0&&new YouTubeProtectedClientSecret(output).Load(Id)=="synthetic-rotated-secret");});
